/*
 * RING_$POLL_STICKY_BPHERR - poll (and clear) the ring's sticky biphase error
 *
 * Original address: 0x00E76290
 * Size: 58 bytes (0x00E76290 .. 0x00E762C9)
 * Generated by: Claude Opus 5.5
 *
 * One argument, (0x8,A6): the address of a longword holding the VA of the
 * ring controller's DCTE (NETWORK_$PAGE_SERVER passes &NETWORK_$RING_DCTE,
 * 0x00E11802).  A Pascal function: the Domain boolean result is in D0.b.
 *
 * Blocks:
 *   0x00E76294-0x00E762A2  dcte = *cell; a non-zero cstatus (DCTE+0x10)
 *                          answers FALSE (`clr.b D0b') and nothing else
 *   0x00E762A4-0x00E762BE  regs = DCTE+0x34; if bit 13 of the mode word
 *                          (+6) is set, the answer is bit 12 of a SECOND
 *                          read of that word (`sne'), else FALSE
 *   0x00E762C0             the mode word is written zero on this arm
 *
 * Quirks reproduced:
 *   - The register word is read twice (0x00E762A8 and 0x00E762B2); it is
 *     memory-mapped I/O, so both reads stay.
 */

#include "ring/ring_internal.h"

/* `btst.l #0xd,D0' 0x00E762AC / `btst.l #0xc,D0' 0x00E762B6 */
#define RING_MODE_STICKY_VALID   0x2000
#define RING_MODE_STICKY_BPHERR  0x1000

int8_t RING_$POLL_STICKY_BPHERR(uint32_t *dcte_cell)
{
    dcte_t *dcte;                       /* A1 */
    ring_hw_regs_t *regs;               /* A0 */
    int8_t result;                      /* D0.b */

    /* 0x00E76294-0x00E762A2 */
    dcte = (dcte_t *)ARCH_VA_TO_PTR(*dcte_cell);
    if (dcte->cstatus != status_$ok) {
        result = 0;
    } else {
        /* 0x00E762A4-0x00E762BE */
        regs = (ring_hw_regs_t *)ARCH_VA_TO_PTR(dcte->disk_dinit);
        if ((regs->mode & RING_MODE_STICKY_VALID) != 0) {
            result = ((regs->mode & RING_MODE_STICKY_BPHERR) != 0) ? (int8_t)-1 : 0;
        } else {
            result = 0;
        }
        /* 0x00E762C0 `move.w #0x0,(0x6,A0)' */
        regs->mode = 0;
    }
    return result;
}
